import{z as A,x as B,o as r,c,q as n,j as l,D as E,d as e,s as o,S as i,b as t}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"写回与写分配","description":"","frontmatter":{"title":"写回与写分配","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/write-back-allocate.md","filePath":"cs/write-back-allocate.md","lastUpdated":1791063341000}'),p={name:"cs/write-back-allocate.md"};function d(D,a,h,m,M,f){const s=B("Mermaid");return r(),c("div",null,[a[2]||(a[2]=n('<h1 id="写回与写分配" tabindex="-1">写回与写分配 <a class="header-anchor" href="#写回与写分配" aria-label="Permalink to &quot;写回与写分配&quot;">​</a></h1><div class="epigraph"><p>写命中可以只改 SRAM 并打脏位，也可以同时改下一层；缺失时可以先把块取来再写，也可以绕过 cache。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/fully-associative">上一课</a>让一块在组内有多路可放，满了用 LRU 踢。<a href="/cs/locality-principle">局部性原理</a>对写同样成立：刚写过的字往往还要写。本课不重讲相联度。缺口是：前面几课几乎只谈读命中。写一旦发生，SRAM 与 DRAM 可能不一致，踢块时必须知道要不要把数据送回。<a href="/cs/memory-array-sram-dram">SRAM 与 DRAM 阵列</a>不能默认两边永远相等。本课只钉写直达/写回，以及写分配/不分配。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>读缺失的语义清楚：把块取进 cache 再读。写命中有两条路：写直达（SRAM 与下一层一起改）或写回（只改 SRAM，置脏位）。写缺失也有两条：写分配（先把块取来再当写命中）或不分配（写绕过 cache 直接去下一层）。缺口不是新的标签格式，而是<strong>这四条组合里哪两条配在一起，以及替换时脏块必须写回</strong>。</p><p>没有脏位，写回无法知道踢谁时要不要访 DRAM。没有写缓冲，写直达会把流水线钉在每条 store 的 DRAM 延迟上。</p><p><span class="marginnote">术语翻译：脏位就是 cache 给每块挂的一枚「已改过、下层那份是旧的」标签。置 1 只花一条位写；它存在的意义是把「付 DRAM 写的账」推迟到替换那刻，中间的多次写全部合并成一次。</span></p><p><span class="marginnote">教学默认「写回 + 写分配」与「写直达 + 不分配」常成对出现。不是物理定律，是常见搭配。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写回：命中只写 SRAM，脏位置 1。替换若选中脏路，先把该块写到下一层，再填入新块。写直达：命中同时写下一层，脏位可省；常用写缓冲把 CPU 与 DRAM 解耦。</p><p>写分配配合写回：缺失时取块，再在 cache 里完成写，后续写命中。不分配配合写直达：一次性写不污染 cache。本课取写回加写分配为后课默认。</p><p><span class="marginnote">数字实例：在一个 64 字节的块上连写 8 个不同字——写直达要发 8 次下层写事务；写回只在 SRAM 里改 8 次、置一次脏位，替换时才发 1 次整块写回。写流量差到 8 倍，就是这么省出来的。</span></p>',12)),(r(),l(i,null,{default:E(()=>[o(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20WH%5B%22%E5%86%99%E5%91%BD%E4%B8%AD%22%5D%20--%3E%20WB%5B%22%E5%86%99%E5%9B%9E%EF%BC%9A%E6%94%B9%20SRAM%EF%BC%8C%E8%84%8F%3D1%22%5D%0A%20%20WH%20--%3E%20WT%5B%22%E5%86%99%E7%9B%B4%E8%BE%BE%EF%BC%9A%E6%94%B9%E4%B8%A4%E5%B1%82%22%5D%0A%20%20WM%5B%22%E5%86%99%E7%BC%BA%E5%A4%B1%22%5D%20--%3E%20WA%5B%22%E5%86%99%E5%88%86%E9%85%8D%EF%BC%9A%E5%A1%AB%E5%9D%97%E5%86%8D%E5%86%99%22%5D%0A%20%20WM%20--%3E%20WNA%5B%22%E4%B8%8D%E5%88%86%E9%85%8D%EF%BC%9A%E7%BB%95%E8%BF%87%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,[e("写回减少对 DRAM 的写流量：一块上的多次写合并成一次替换时的写回。代价是层次之间暂时不一致。单核、无 DMA 时，CPU 总从 cache 读，看不见这个问题；"),t("a",{href:"/cs/coherence-intro"},"一致性问题引入"),e("会把它重新打开。")],-1)),a[5]||(a[5]=t("p",null,"被选中替换的块走哪条路：",-1)),(r(),l(i,null,{default:E(()=>[o(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20EV%5B%22%E6%9F%90%E5%9D%97%E8%A2%AB%E9%80%89%E4%B8%AD%E6%9B%BF%E6%8D%A2%22%5D%20--%3E%20Q%7B%22%E8%84%8F%E4%BD%8D%E6%98%AF%201%20%E5%90%97%22%7D%0A%20%20Q%20--%3E%7C%22%E6%98%AF%22%7C%20WB%5B%22%E5%85%88%E6%95%B4%E5%9D%97%E5%86%99%E5%9B%9E%E4%B8%8B%E4%B8%80%E5%B1%82%22%5D%0A%20%20Q%20--%3E%7C%22%E5%90%A6%22%7C%20FILL%5B%22%E7%9B%B4%E6%8E%A5%E5%A1%AB%E5%85%A5%E6%96%B0%E5%9D%97%22%5D%0A%20%20WB%20--%3E%20FILL%0A%20%20FILL%20--%3E%20NEW%5B%22%E6%96%B0%E5%9D%97%E6%A0%87%E8%AE%B0%E4%B8%BA%E5%B9%B2%E5%87%80%22%5D%0A%20%20NEW%20--%3E%20NEXT%5B%22%E5%90%8E%E7%BB%AD%E5%86%99%E5%86%8D%E7%BD%AE%E8%84%8F%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p>写缓冲让写直达的 store 不必等 DRAM 完成即可提交，但缓冲与后续 load 之间要做转发或探测，否则读到旧 DRAM。本课只承认缓冲存在，不把实现写完。</p><p><span class="marginnote">常见误区：以为写回期间数据「丢了」。没有——SRAM 里始终是最新的副本，只是层次之间暂时不一致。真正的风险在旁路者（DMA、另一个核）不看 cache 就去读 DRAM，那是一致性课要接管的场景。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 MESI，不处理多核。也不把脏位与操作系统的脏页混名：页的脏是虚拟内存课的对象，粒度是页不是 cache 行。I/O DMA 绕过 cache 时，写回的不一致会变成正确性问题，那是一致性课的缺口。</p><p>后课默认：数据 cache 写回且写分配；替换脏块先写下一层。缺失分类仍可以把写缺失算进去。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>写回改 SRAM 打脏位，替换时才写下一层；写直达两边一起改。</li><li>写分配在缺失时填块；不分配绕过。</li><li>多副本如何达成一致是后课的缺口。</li><li>出处：Patterson and Hennessy, <em>COD</em> RISC-V；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',7))])}const R=A(p,[["render",d]]);export{C as __pageData,R as default};
